class Task:
    def __init__(self, C_LO, C_HI, D, T, L):
        self.C_LO = C_LO
        self.C_HI = C_HI
        self.D = D
        self.T = T
        self.L = L

def get_task_subsets(task_set):
    LO_tasks = [t for t in task_set if t.L == 'LO']
    HI_tasks = [t for t in task_set if t.L == 'HI']
    return LO_tasks, HI_tasks

def compute_utilizations(task_set, HI_tasks):
    U_LO_total = 0
    U_HI_total = 0
    for task in task_set:
        U_LO_total += task.C_LO / task.T
    for task in HI_tasks:
        U_HI_total += task.C_HI / task.T
    return U_LO_total, U_HI_total

def is_valid_sbf(sbf_func):
    if sbf_func(0) != 0:
        return False
    # Check unit speed property (simplified for sketch)
    for delta in range(1, 100):
        for k in range(1, 10):
            if sbf_func(delta + k) - sbf_func(delta) > k:
                return False
    return True

def is_edf_schedulable_non_mc(task_set, sbf_func, max_delta):
    for delta in range(0, max_delta + 1):
        total_demand = 0
        for task_i in task_set:
            # Assuming a standard dbf calculation for non-MC tasks
            num_jobs = max(0, (delta - task_i.D) // task_i.T + 1)
            total_demand += num_jobs * task_i.C

        if total_demand > sbf_func(delta):
            return False # Not schedulable
    return True # Schedulable

class Job:
    def __init__(self, task_id, release_time, deadline, criticality_level):
        self.task_id = task_id
        self.release_time = release_time
        self.deadline = deadline
        self.criticality_level = criticality_level
        self.is_finished = False

def identify_carry_over_jobs(active_jobs, switch_time):
    carry_over_jobs = []
    for job in active_jobs:
        if job.criticality_level == 'HI' and not job.is_finished:
            carry_over_jobs.append(job)
    return carry_over_jobs

class Task:
    # ... (previous attributes)
    def __init__(self, C_LO, C_HI, D, T, L):
        # ...
        self.D_LO = D # Default, will be tuned for HI tasks
        self.D_HI = D # True deadline

def set_adjusted_deadlines(task_set):
    for task in task_set:
        if task.L == 'LO':
            task.D_LO = task.D # Low-criticality tasks use true deadline
        elif task.L == 'HI':
            task.D_HI = task.D # High-criticality tasks' true deadline
            # D_LO will be tuned later, but must satisfy C_LO <= D_LO <= D_HI
            task.D_LO = task.D # Initialize D_LO to D_HI, then tune downwards

def dbf_LO(task_i, delta):
    num_jobs = (delta - task_i.D_LO) // task_i.T + 1
    return max(0, num_jobs) * task_i.C_LO

def full_HI(task_i, delta):
    num_jobs = (delta - task_i.D_HI) // task_i.T + 1
    return max(0, num_jobs) * task_i.C_HI

def done_carry_over_work(task_i, delta_rem_window):
    if task_i.D_HI > delta_rem_window and delta_rem_window >= (task_i.D_HI - task_i.D_LO):
        return max(0, task_i.C_LO - delta_rem_window + task_i.D_HI - task_i.D_LO)
    else:
        return 0

def check_A_delta(task_set, sbf_LO_func, delta):
    total_demand_LO = 0
    for task in task_set:
        total_demand_LO += dbf_LO(task, delta)
    return total_demand_LO <= sbf_LO_func(delta)

def check_B_delta(HI_tasks, sbf_HI_func, delta):
    total_demand_HI = 0
    for task in HI_tasks:
        total_demand_HI += dbf_HI(task, delta)
    return total_demand_HI <= sbf_HI_func(delta)

def is_edf_schedulable_mc(task_set, HI_tasks, sbf_LO_func, sbf_HI_func, max_delta):
    for delta in range(0, max_delta + 1):
        if not check_A_delta(task_set, sbf_LO_func, delta):
            return False # Condition A failed
        if not check_B_delta(HI_tasks, sbf_HI_func, delta):
            return False # Condition B failed
    return True # Both conditions hold, schedulable

class NonMCTask:
    def __init__(self, C, D, T):
        self.C = C
        self.D = D
        self.T = T

def map_f_LO(task_i):
    return NonMCTask(task_i.C_LO, task_i.D_LO, task_i.T)

def map_f_HI(task_i):
    # The deadline D_i_HI - D_i_LO is crucial here for 'done' mapping
    return NonMCTask(task_i.C_HI, task_i.D_HI - task_i.D_LO, task_i.T)

