def calculate_weighted_acceptance_ratio(acceptance_ratios_by_U):
    # acceptance_ratios_by_U is a dictionary {U: A(U)}
    sum_weighted_acceptance = 0
    sum_U = 0
    for U, A_U_val in acceptance_ratios_by_U.items():
        sum_weighted_acceptance += U * A_U_val
        sum_U += U
    if sum_U == 0: return 0 # Avoid division by zero
    return sum_weighted_acceptance / sum_U
